FROM StockMoves WHERE StockID=116977;
SELECT 'HEADER' c, ID, DocumentID, DocNumber, Status, AccountKey, AccountName, TFtal, TFtalVat FROM Stock WHERE ID=@sid;
SELECT 'LINES' c, StockID, DocumentID, ItemKey, ItemName, Quantity, Price, DiscountPrc, TFtal, Tree, LineNum, Status FROM StockMoves WHERE StockID=@sid;
COMMIT;
